import{_ as a,o as r,c as t,a3 as o}from"./chunks/framework.CJlOecQn.js";const d=JSON.parse('{"title":"Emergencies and important numbers","description":"Who to call in Qatar for police, fire, ambulance, power or water emergencies, what to say, the service for deaf people, and what to do after a minor road accident.","frontmatter":{"title":"Emergencies and important numbers","description":"Who to call in Qatar for police, fire, ambulance, power or water emergencies, what to say, the service for deaf people, and what to do after a minor road accident.","lastChecked":"2026-10","sourceCount":11},"headers":[],"relativePath":"guide/emergencies.md","filePath":"guide/emergencies.md"}'),n={name:"guide/emergencies.md"};function f(s,e,i,l,c,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="emergencies-and-important-numbers" tabindex="-1">Emergencies and important numbers <a class="header-anchor" href="#emergencies-and-important-numbers" aria-label="Permalink to &quot;Emergencies and important numbers&quot;">​</a></h1><p>In an emergency, call 999. Save the numbers on this page in your phone now, and teach them to your family.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><h2 id="_999" tabindex="-1">999 <a class="header-anchor" href="#_999" aria-label="Permalink to &quot;999&quot;">​</a></h2><p>The Ministry of Interior&#39;s Emergency Services Section takes criminal, fire and medical emergency calls on 999, around the clock. It has staff who can translate several languages, including English, French, Chinese, Filipino and Urdu.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup> It also passes accident reports to the right authority.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></p><p>When you call, give your name, your phone number, the nature of the emergency and your exact location.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup> Speak clearly, answer the operator&#39;s questions and follow the instructions you are given.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></p><h2 id="ambulance" tabindex="-1">Ambulance <a class="header-anchor" href="#ambulance" aria-label="Permalink to &quot;Ambulance&quot;">​</a></h2><p>Call 999 for a condition that needs immediate medical help to save a life, such as stroke, chest pain, a severe allergic reaction, a seizure or difficulty breathing.<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4]</a></sup> Hamad Medical Corporation (HMC) says people with conditions that are not life-threatening should not dial 999, and should use urgent care if it cannot wait.<sup class="footnote-ref"><a href="#fn4" id="fnref4:2">[4]</a></sup></p><h2 id="if-you-are-deaf" tabindex="-1">If you are deaf <a class="header-anchor" href="#if-you-are-deaf" aria-label="Permalink to &quot;If you are deaf&quot;">​</a></h2><p>The Ministry of Interior runs an Emergency Service for the Deaf on 992, around the clock. The ministry&#39;s page limits it to deaf users.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup> You can reach it in three ways:</p><ul><li>A video call to 992 from a computer or mobile phone.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></li><li>An SMS to 992.<sup class="footnote-ref"><a href="#fn5" id="fnref5:2">[5]</a></sup></li><li>An email to <a href="mailto:992@moi.gov.qa" target="_blank" rel="noreferrer">992@moi.gov.qa</a>.<sup class="footnote-ref"><a href="#fn5" id="fnref5:3">[5]</a></sup></li></ul><p>In an SMS, state clearly the problem and the service you need, such as ambulance, civil defence or police, plus your name, your address and any injuries or deaths.<sup class="footnote-ref"><a href="#fn5" id="fnref5:4">[5]</a></sup> SMS can be delayed by the mobile network, so do not rely on it alone. Make sure your message has arrived by contacting the police.<sup class="footnote-ref"><a href="#fn5" id="fnref5:5">[5]</a></sup> Misuse of this service can lead to legal action.<sup class="footnote-ref"><a href="#fn5" id="fnref5:6">[5]</a></sup></p><h2 id="finding-emergency-care" tabindex="-1">Finding emergency care <a class="header-anchor" href="#finding-emergency-care" aria-label="Permalink to &quot;Finding emergency care&quot;">​</a></h2><p>For a life-threatening emergency, call 999 or go to the nearest HMC Emergency Department.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><ul><li><strong>Adults:</strong> Hamad General Hospital Trauma and Emergency Center, Al Wakra, Al Khor, Hazm Mebaireek General, Aisha Bint Hamad Al Attiyah and The Cuban Hospital.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li><strong>Pregnancy and gynaecology emergencies:</strong> Women&#39;s Wellness and Research Center.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li><strong>Children under 14:</strong> the Pediatric Emergency Centers at Al Sadd, Airport, Al Rayyan, Al Wakra, Al Khor and Aisha Bint Hamad Al Attiyah Hospital.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li><strong>Urgent but not life-threatening:</strong> the Primary Health Care Corporation (PHCC) runs 16 Urgent Care Units, open 24 hours, seven days a week. You need no appointment.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li></ul><p>If you are not sure where to go, call 16000. Choose option 2 then option 2 for PHCC urgent consultation, or option 3 then option 1 for HMC urgent consultation, which runs 8 am to 3 pm, Sunday to Thursday.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></p><h2 id="after-a-road-accident" tabindex="-1">After a road accident <a class="header-anchor" href="#after-a-road-accident" aria-label="Permalink to &quot;After a road accident&quot;">​</a></h2><p>If anyone is seriously hurt, call 999 for an ambulance.<sup class="footnote-ref"><a href="#fn4" id="fnref4:3">[4]</a></sup></p><p>For a minor accident between two vehicles, you can register it in the Metrash2 app instead of going to traffic investigation in person:<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></p><ol><li>Take up to 4 photos of each vehicle, with one clearly showing the number plate.<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6]</a></sup></li><li>Move the vehicles away from the scene and park off the road.<sup class="footnote-ref"><a href="#fn6" id="fnref6:2">[6]</a></sup></li><li>Turn on location services on your phone.<sup class="footnote-ref"><a href="#fn6" id="fnref6:3">[6]</a></sup></li><li>In Metrash2, open Traffic Services, then Accident Report.<sup class="footnote-ref"><a href="#fn6" id="fnref6:4">[6]</a></sup></li><li>Enter both vehicles&#39; details: vehicle number, QID number and mobile number.<sup class="footnote-ref"><a href="#fn6" id="fnref6:5">[6]</a></sup></li><li>Attach the photos, confirm the data is correct and submit.<sup class="footnote-ref"><a href="#fn6" id="fnref6:6">[6]</a></sup></li><li>Wait for the text messages. After traffic investigators review the photos, both drivers are told to go to the insurance company or are given approval for the repair.<sup class="footnote-ref"><a href="#fn6" id="fnref6:7">[6]</a></sup></li></ol><p>The Ministry of Interior also lists printing traffic accident reports among its traffic services, for repairing damaged vehicles.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></p><h2 id="power-or-water-emergency" tabindex="-1">Power or water emergency <a class="header-anchor" href="#power-or-water-emergency" aria-label="Permalink to &quot;Power or water emergency&quot;">​</a></h2><p>Kahramaa treats it as an emergency when your power or water is cut without prior warning from Kahramaa.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup> Call 991 at any hour, or email <a href="mailto:991@km.com.qa" target="_blank" rel="noreferrer">991@km.com.qa</a>.<sup class="footnote-ref"><a href="#fn8" id="fnref8:1">[8]</a></sup> Have your electricity and water number ready, because the phone system needs it.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup></p><h2 id="quick-list" tabindex="-1">Quick list <a class="header-anchor" href="#quick-list" aria-label="Permalink to &quot;Quick list&quot;">​</a></h2><ul><li><strong>999:</strong> police, fire and medical emergencies.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li><strong>992:</strong> emergency service for deaf people.<sup class="footnote-ref"><a href="#fn5" id="fnref5:7">[5]</a></sup></li><li><strong>991:</strong> Kahramaa electricity and water emergencies.<sup class="footnote-ref"><a href="#fn9" id="fnref9:1">[9]</a></sup></li><li><strong>4439 6066:</strong> Pediatric Emergency Center hotline, 24 hours.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li><strong>16000:</strong> National Healthcare Helpline.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></li><li><strong>107:</strong> PHCC, including urgent or same day appointments.<sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup></li><li><strong>16060:</strong> HMC Nesma&#39;ak Patient Contact Center, 24 hours.<sup class="footnote-ref"><a href="#fn11" id="fnref11">[11]</a></sup></li></ul><p>See also: <a href="./health">Health care and insurance</a>, <a href="./metrash">Metrash</a>, <a href="./driving">Driving</a>, <a href="./housing-and-utilities">Housing and utilities</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Hamad Medical Corporation, <a href="https://www.hamad.qa/EN/Hospitals-and-services/Emergency-Care-Services/Pages/Emergency-and-Urgent-Care-Services.aspx" target="_blank" rel="noreferrer">Emergency and Urgent Care Services</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/UNCCPCJDoha/English/Emergency_Services.html" target="_blank" rel="noreferrer">Emergency Services (999-992)</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Hamad Medical Corporation, <a href="https://www.hamad.qa/EN/Hospitals-and-services/Ambulance-Service/Rescue-Process/Pages/default.aspx" target="_blank" rel="noreferrer">Rescue Process</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Hamad Medical Corporation, <a href="https://hamad.qa/EN/Emergency/Pages/Life-ThreateningMedicalEmergency.aspx" target="_blank" rel="noreferrer">Life-Threatening Medical Emergency</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:3" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/infocenter/emerservicedeaf" target="_blank" rel="noreferrer">Emergency Service for the Deaf</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:7" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/departmentcommittees/gatraffic/!ut/p/z1/jY_NDoIwEIQfqdOCpBxrNfwUbQytwF5MT4ZE0YPx-SXEq5U9zSbfzGQYsZ7RFN7jNbzGxxRu8z9QdjnmUDy3MNapWe6Ls9epFMgF6xagUjItObiRJSRU62q3tVoAnNEaP36cwjp_BKB4fMdoQepyVyFpYYomS-YFzUELfQLk5gvEJv4red697zFWH0zJlfc!/?1dmy=&amp;urile=wcm:path:/wcmlib-internet-en/sa-departmentcommittee/generaladministrationoftraffic/minor+accident" target="_blank" rel="noreferrer">Minor Road Accident Registration via Metrash2</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref6:7" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn7" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/trafficservices" target="_blank" rel="noreferrer">Traffic Services</a>. Last checked: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn8" class="footnote-item"><p>Kahramaa, <a href="https://www.km.qa/CustomerService/Pages/ServiceDetails.aspx?ItemID=28" target="_blank" rel="noreferrer">Emergency and service related problems</a>. Last checked: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref8:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn9" class="footnote-item"><p>Kahramaa, <a href="https://km.qa/Pages/call-center.aspx?IsDlg=1" target="_blank" rel="noreferrer">Call Center 991</a>. Last checked: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref9:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn10" class="footnote-item"><p>Primary Health Care Corporation, <a href="https://www.phcc.gov.qa/patients-clients/eservice-guestpage/register-new-health-card" target="_blank" rel="noreferrer">Register New Health Card</a>. Last checked: 2026-10. <a href="#fnref10" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn11" class="footnote-item"><p>Hamad Medical Corporation, <a href="https://hamad.qa/EN/news/2025/March/Pages/Easier-Than-Ever-to-Manage-Your-Specialist-Appointment.aspx" target="_blank" rel="noreferrer">It&#39;s Easier Than Ever to Manage Your Specialist Appointment at Hamad Medical Corporation</a>. Last checked: 2026-10. <a href="#fnref11" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',28)])])}const u=a(n,[["render",f]]);export{d as __pageData,u as default};
